import os
import random
import numpy as np
import torch


class Config:
    """
    Configuration for Diabetic Retinopathy Severity Prediction (Idea 5).
    Uses ConvNeXt-Tiny with LayerNorm to handle 512x512 resolution.
    """

    # =======================
    # General Settings
    # =======================
    seed = 42
    debug = False  # Set to True to train on a small subset for debugging
    num_workers = 4

    # =======================
    # File Paths
    # =======================
    input_dir = "./input"
    metadata_dir = "./metadata"

    # Metadata paths (generated by the provided script)
    train_meta_path = os.path.join(metadata_dir, "train.csv")
    val_meta_path = os.path.join(metadata_dir, "val.csv")
    test_meta_path = os.path.join(metadata_dir, "test.csv")

    # Output paths
    working_dir = "./working/idea_5"
    model_save_path = os.path.join(working_dir, "best_model.pth")
    submission_path = os.path.join(working_dir, "submission.csv")

    # =======================
    # Model Hyperparameters
    # =======================
    model_name = "convnext_tiny.fb_in1k"
    image_size = 512

    # Ordinal Regression: 4 binary outputs
    # (Prob > 0, Prob > 1, Prob > 2, Prob > 3)
    num_outputs = 4

    # Regularization
    dropout_rate = 0.5
    drop_path_rate = 0.1  # Stochastic depth for ConvNeXt

    # =======================
    # Training Hyperparameters
    # =======================
    epochs = 15
    batch_size = 16  # Fits 512x512 on A100 easily

    # Optimizer (AdamW)
    learning_rate = 2e-4
    weight_decay = 0.05  # Standard for ConvNeXt

    # Scheduler (Cosine Annealing)
    min_lr = 1e-6

    # Gradient Clipping
    max_grad_norm = 1.0

    # =======================
    # Setup & Utilities
    # =======================
    @classmethod
    def setup(cls):
        """
        Prepares the environment:
        1. Creates the working directory.
        2. Sets random seeds for reproducibility.
        """
        # Create output directory
        os.makedirs(cls.working_dir, exist_ok=True)

        # Set seeds
        cls.set_seed()

    @classmethod
    def set_seed(cls):
        """Sets seeds for random, numpy, and torch."""
        random.seed(cls.seed)
        np.random.seed(cls.seed)
        torch.manual_seed(cls.seed)
        torch.cuda.manual_seed(cls.seed)

        # Ensure deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
